SELECT , au.`nick_name` AS answerNickName FROM tb_blog_comments c LEFT JOIN tb_user u ON c.user_id = u.id LEFT JOIN tb_blog_comments ac ON c.answer_id = ac.id LEFT JOIN tb_user au ON ac.user_id = au.id WHERE c.parent_id IN
#{parentId}
AND (c.status IS NULL OR c.status = 0) ORDER BY c.parent_id ASC, c.id ASC LIMIT 1000

SELECT c.`parent_id` AS parentId, COUNT(*) AS replyCount FROM tb_blog_comments c WHERE c.parent_id IN
#{parentId}
AND (c.status IS NULL OR c.status = 0) GROUP BY c.parent_id

mapper.update:
UPDATE tb_blog b
SET b.comments = (
    SELECT COUNT(*) FROM tb_blog_comments c
    WHERE c.blog_id = b.id AND (c.status IS NULL OR c.status = 0)
)
WHERE b.id = #{blogId}
